local ClayDigger = {}
local PRODUCTS = {
    common_clay = { name = "Navadna glina", clayBedCost = 1, time = 1, cost = 8, quality = 30, description = "Navadna glina iz rečnih bregov." },
    red_clay = { name = "Rdeča glina", clayBedCost = 1, time = 2, cost = 20, quality = 50, prestige = 1, description = "Rdeča glina z bogato barvo." },
    white_kaolin = { name = "Beli kaolin", kaolinBedCost = 1, time = 3, cost = 50, quality = 65, prestige = 2, happiness = 1, description = "Beli kaolin za porcelan." },
    fire_clay = { name = "Ognjevzdržna glina", fireClayBedCost = 1, time = 4, cost = 120, quality = 80, prestige = 5, happiness = 2, description = "Ognjevzdržna glina za peči." },
    silver_dust_clay = { name = "Srebrno prašna glina", kaolinBedCost = 1, silverCost = 1, time = 7, cost = 280, quality = 92, prestige = 11, happiness = 3, description = "Glina s srebrnim prahom za fine izdelke." },
    royal_grand_clay = { name = "Kraljevski veliki glina", kaolinBedCost = 2, goldCost = 1, silverCost = 1, jewelCost = 1, time = 12, cost = 1200, quality = 100, prestige = 33, happiness = 7, description = "Velika kraljevska glina z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Glinaška postaja", cost = { gold = 200, wood = 100, stone = 150 }, upkeep = 5, qualityBonus = 5 },
    clay_pit = { name = "Glinokop", cost = { gold = 700, wood = 200, stone = 350, iron = 6 }, upkeep = 17, qualityBonus = 18 },
    washing_house = { name = "Pralnica", cost = { gold = 1800, wood = 300, stone = 500, silver = 25, water = 10 }, upkeep = 45, qualityBonus = 30 },
    royal_clay_atelier = { name = "Kraljevski atelje gline", cost = { gold = 7500, wood = 500, stone = 900, gold = 60, jewel = 20 }, upkeep = 150, qualityBonus = 55, prestigeBonus = 40 },
}
ClayDigger.clayBedStock = 22; ClayDigger.kaolinBedStock = 14; ClayDigger.fireClayBedStock = 10; ClayDigger.silverStock = 8; ClayDigger.goldStock = 6; ClayDigger.jewelStock = 6
ClayDigger.productStock = {}; ClayDigger.buildings = {}; ClayDigger.maker = nil; ClayDigger.activeMaking = {}; ClayDigger.totalProducts = 0; ClayDigger.dayTimer = 0
function ClayDigger.init() ClayDigger.clayBedStock=22; ClayDigger.kaolinBedStock=14; ClayDigger.fireClayBedStock=10; ClayDigger.silverStock=8; ClayDigger.goldStock=6; ClayDigger.jewelStock=6; ClayDigger.productStock={}; ClayDigger.buildings={}; ClayDigger.maker=nil; ClayDigger.activeMaking={}; ClayDigger.totalProducts=0; ClayDigger.dayTimer=0; print("[ClayDigger] Royal Clay Digger System initialized (6 products, 4 buildings)") end
function ClayDigger.hireMaker(n,s) s=s or math.random(45,85); local c=440+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ClayDigger.maker={name=n or ("Glinaš "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Glinaš najet: %s (spretnost: %d)",ClayDigger.maker.name,s),"success") end; return true end
function ClayDigger.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ClayDigger.build(id) local ok,e=ClayDigger.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ClayDigger.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ClayDigger.getQualityBonus() local b=0; for _,bd in ipairs(ClayDigger.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ClayDigger.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.clayBedCost and ClayDigger.clayBedStock<(d.clayBedCost or 0) then return false,"Premalo glinastih postelj" end; if d.kaolinBedCost and ClayDigger.kaolinBedStock<(d.kaolinBedCost or 0) then return false,"Premalo kaolinskih postelj" end; if d.fireClayBedCost and ClayDigger.fireClayBedStock<(d.fireClayBedCost or 0) then return false,"Premalo ognjevzdržnih glin" end; if d.silverCost and ClayDigger.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ClayDigger.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ClayDigger.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #ClayDigger.buildings==0 then return false,"Potrebna delavnica" end; if not ClayDigger.maker then return false,"Potreben glinaš" end; return true end
function ClayDigger.make(pt,qty) qty=qty or 10; local ok,e=ClayDigger.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.clayBedCost then ClayDigger.clayBedStock=ClayDigger.clayBedStock-d.clayBedCost*qty end; if d.kaolinBedCost then ClayDigger.kaolinBedStock=ClayDigger.kaolinBedStock-d.kaolinBedCost*qty end; if d.fireClayBedCost then ClayDigger.fireClayBedStock=ClayDigger.fireClayBedStock-d.fireClayBedCost*qty end; if d.silverCost then ClayDigger.silverStock=ClayDigger.silverStock-d.silverCost*qty end; if d.goldCost then ClayDigger.goldStock=ClayDigger.goldStock-d.goldCost*qty end; if d.jewelCost then ClayDigger.jewelStock=ClayDigger.jewelStock-d.jewelCost*qty end; local t=d.time; if ClayDigger.maker then t=math.max(1,t-math.floor(ClayDigger.maker.skill/12)) end; table.insert(ClayDigger.activeMaking,{id="clay_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,quality=d.quality or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ClayDigger.completeMaking(m) local q=1.0+(ClayDigger.getQualityBonus()/100); if ClayDigger.maker then q=q+(ClayDigger.maker.skill/180) end; q=math.min(2.0,q); ClayDigger.productStock[m.productType]=(ClayDigger.productStock[m.productType] or 0)+m.quantity; ClayDigger.totalProducts=ClayDigger.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ClayDigger.maker then ClayDigger.maker.itemsMade=ClayDigger.maker.itemsMade+m.quantity; if math.random()<0.20 then ClayDigger.maker.skill=math.min(100,ClayDigger.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Glina izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"clay.completed",{productName=m.productName,quality=m.quality}) end end
function ClayDigger.update(dt) if not _G.state then return end; ClayDigger.dayTimer=ClayDigger.dayTimer+dt; if ClayDigger.dayTimer>=30 then ClayDigger.dayTimer=0; for i=#ClayDigger.activeMaking,1,-1 do local m=ClayDigger.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ClayDigger.completeMaking(m); table.remove(ClayDigger.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ClayDigger.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ClayDigger.maker then tu=tu+11 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ClayDigger.getStats() return {clayBedStock=ClayDigger.clayBedStock,kaolinBedStock=ClayDigger.kaolinBedStock,fireClayBedStock=ClayDigger.fireClayBedStock,silverStock=ClayDigger.silverStock,goldStock=ClayDigger.goldStock,jewelStock=ClayDigger.jewelStock,productStock=ClayDigger.productStock,numBuildings=#ClayDigger.buildings,hasMaker=ClayDigger.maker~=nil,makerName=ClayDigger.maker and ClayDigger.maker.name or "—",makerSkill=ClayDigger.maker and ClayDigger.maker.skill or 0,activeMaking=#ClayDigger.activeMaking,totalProducts=ClayDigger.totalProducts} end
return ClayDigger
